fn ann(u:[u64;4],v:[u64;3])->Vec<Vec<u64>>{let mut a=vec![vec![0;10];3];for(k,(x,y,_))in model::Model::monomials().iter().enumerate(){let p=mm(&mpow(vec![0,1],*x as u64,&u),&mpow(v.to_vec(),*y as u64,&u),&u);for i in 0..3{a[i][k]=p.get(i).copied().unwrap_or(0);}}a}
fn main(){let construction=phase::Span::new("model_construction");let model=model::Model::new();drop(construction);for label in ["D1","B"]{let _input=phase::Span::new(&format!("input_{label}"));let dir="../hec_directsymmetric631_20261116";let result=if label=="B"{"job-B.res"}else{"solve-D1.res"};let(e,x)=exact::checked(&format!("{dir}/generated-{label}/target.ms"),&format!("{dir}/{result}"));let roots:Vec<_>=(0..631).filter(|&r|eval(&e,r)==0).collect();assert_eq!(roots.len(),2);let lambda=input(&format!("../hec_inputcoords631_20261116/coordinates/{label}-KUMMER.txt"));let next=input(&format!("../hec_inputcoords631_20261116/coordinates/{label}-NEXT-KUMMER.txt"));let offset=fs::read_to_string(format!("../hec_inputcoords631_20261116/coordinates/{label}-OFFSET.txt")).unwrap().trim().parse().unwrap();let mut images=HashSet::new();let mut rows=vec![];for r in roots{let _candidate=phase::Span::new(&format!("candidate_{label}_{r}"));let values:Vec<_>=x.iter().map(|p|eval(p,r)).collect();let u=[values[1],values[2],values[3],1];let v=[values[4],values[5],values[6]];assert_eq!(gcd(u.to_vec(),deriv(&u)),vec![1]);let a=ann(u,v);let(image,positive)=model.candidate(a.clone(),lambda,next,offset).expect("direct_candidate_failed");let mut bad=next;bad[0]=(bad[0]+1)%631;assert!(model.candidate(a,lambda,bad,offset).is_none());images.insert(image);let mut row=vec![positive as u64,offset];row.extend(u);row.extend(v);rows.push(row.iter().map(u64::to_string).collect::<Vec<_>>().join(" "));println!("DIRECT_CANDIDATE label={label} root={r} positive={positive} u={u:?} v={v:?} adjacency_verified=true");}assert_eq!(images.len(),1);let image=images.into_iter().next().unwrap();fs::write(format!("class-{label}.txt"),image.map(|a|a.to_string()).join(" ")+"\n").unwrap();fs::write(format!("divisors-{label}.txt"),rows.join("\n")+"\n").unwrap();println!("PASS_DIRECT_CLASS label={label} candidates=2 unique_class=1 corrupt_adjacency_rejected=true");}phase::report();println!("PASS both_direct_output_classes_recovered=true old_class_or_scalar_not_loaded=true timing_claim=false");}
